// Quality — NCR & deliverables view models against the prototype's own render values (quality.golden.json, generated by
// scripts/proto-golden-quality.ts from design lines 3096–5239, renderValsEN and renderVals in French) on the seeded
// in-memory database — the NCRs read through the Vigie quality connector (mock over the seeded mirror), the deliverables
// from Keystone's register — in EN and FR, for the six projects with data: register switch, KPI tiles, chips, rows, both
// drawers, the client's view, and a project without data. Deliberate deviations are listed and asserted explicitly.
import { beforeAll, describe, expect, it } from 'vitest';
import { makeT, type Lang } from '@/i18n/translate';
import { setDb } from '@/server/db/client';
import { openDatabase } from '@/server/db/open';
import { getQualityScreen } from '@/server/dal/quality-screen';
import GOLD from './quality.golden.json';
import { dlvDrawerView, dlvTabView, ncrDrawerView, ncrTabView, qualitySegView, type QualityState, type QualityViewerCtx } from './model';

/* eslint-disable @typescript-eslint/no-explicit-any */
const G = GOLD as any;
const LANGS: Lang[] = ['en', 'fr'];
const DATA = ['HLT-026', 'NDC-031', 'RCF-019', 'ERP-202', 'WSA-044', 'MSR-012'];
const S0: QualityState = { tab: 'ncr', filter: null, status: null, ncr: null, dlv: null };
const DIRECTOR: QualityViewerCtx = { role: 'director', canEdit: true, isClientContact: false, vigie: true };
const PM: QualityViewerCtx = { role: 'pm', canEdit: true, isClientContact: false, vigie: true };
const CLIENT: QualityViewerCtx = { role: 'client', canEdit: true, isClientContact: true, vigie: false };

/** Zero-padded prototype dates ("02 Sep", FR "02 sept.") are written "2 Sep" (as the Delivery 4 data layer). */
const day = (s: string) => s.replace(/(^|· )0(\d)/g, '$1$2');
/**
 * Deliberate French deviations (applied to the golden values before comparing): the step of "Move to …" translated;
 * singular KPI subs; deliverable types and ISO 9001 clause titles the prototype left in English; "comments issued".
 */
const FR_FIX: [RegExp, string][] = [
  [/^Passer à (.+)$/, ''],
  [/^([01]) clôturées ce trimestre$/, '$1 clôturée ce trimestre'],
  [/^Calculation notes$/, 'Notes de calcul'],
  [/^Test & inspection reports$/, 'Rapports d’essais et d’inspection'],
  [/^Manuals \/ as-built$/, 'Manuels / plans de récolement'],
  [/^Certificates \(CE, lifting…\)$/, 'Certificats (CE, levage…)'],
  [/^Client acceptance \(PV de réception\)$/, 'Réception client (PV de réception)'],
  // ISO 9001 clause titles the prototype left in English (official French titles).
  [/^8\.7 Control of nonconforming outputs$/, '8.7 Maîtrise des éléments de sortie non conformes'],
  [/^8\.4 Externally provided processes$/, '8.4 Processus fournis par des prestataires externes'],
  [/^8\.5\.6 Control of changes$/, '8.5.6 Maîtrise des modifications'],
  [/^ISO 9001 · 8\.6 Release of products and services$/, 'ISO 9001 · 8.6 Libération des produits et services'],
];
const STEP_FR: Record<string, string> = { Containment: 'Confinement', 'Root cause': 'Cause racine', 'Corrective action': 'Action corrective', Verification: 'Vérification', Closed: 'Clôturée' };
const fix = (lang: Lang, s: string) => {
  if (lang !== 'fr' || typeof s !== 'string') return s;
  const m = /^Passer à (.+)$/.exec(s);
  if (m) return `Passer à ${STEP_FR[m[1]] ?? m[1]}`;
  return FR_FIX.reduce((x, [re, rep]) => (rep ? x.replace(re, rep) : x), s);
};

beforeAll(async () => {
  setDb(await openDatabase());
}, 60_000);

const screen = (code: string) => getQualityScreen(code);
const ncrTab = async (code: string, lang: Lang, state: QualityState = S0, viewer = DIRECTOR) => {
  const s = await screen(code);
  return ncrTabView({ code, ncrs: s.ncrs, state, viewer, today: s.today, dataDate: s.dataDate }, makeT(lang), lang);
};
const dlvTab = async (code: string, lang: Lang, state: QualityState = { ...S0, tab: 'dlv' }, viewer = PM) => {
  const s = await screen(code);
  return dlvTabView({ code, deliverables: s.deliverables, state, viewer, today: s.today }, makeT(lang), lang);
};

describe('register switch', () => {
  it.each(LANGS)('%s: two options (links keep the chip filters)', (lang) => {
    const seg = qualitySegView('HLT-026', { ...S0, filter: 'major', status: 'submitted', ncr: 'NCR-026' }, makeT(lang));
    expect(seg.map((o) => o.label)).toEqual(G[lang].qSeg.map((o: any) => o.label));
    expect(seg.map((o) => o.href)).toEqual(['/projects/HLT-026/quality?filter=major&status=submitted', '/projects/HLT-026/quality?tab=dlv&filter=major&status=submitted']);
  });
});

describe('NCR log — EN and FR', () => {
  it.each(LANGS)('%s: KPI tiles, chips and rows of every project with data', async (lang) => {
    for (const code of DATA) {
      const g = G[lang].projects[code].ncr;
      const v = await ncrTab(code, lang);
      expect(v.kpis, code).toEqual(g.kpis.map((k: any) => ({ label: k.label, value: k.value, sub: fix(lang, k.sub), color: k.color })));
      expect(v.chips.map((c) => ({ label: c.label, count: c.count })), code).toEqual(g.chips);
      expect(v.rows.map((r) => ({
        id: r.number, title: r.title, raised: r.raisedLine, sev: r.severity, sevClass: r.severityClass, src: r.source, actText: r.activity, owner: r.owner, due: r.due,
        costText: r.cost, status: r.status, tagClass: r.statusClass, steps: r.segments, next: r.action?.label ?? null,
      })), code).toEqual(g.rows.map((r: any) => ({
        id: r.id, title: r.title, raised: `${r.raised} · ${day(r.date)}`, sev: r.sev, sevClass: r.sevClass, src: r.src, actText: r.actText, owner: r.owner, due: r.due,
        costText: r.costText, status: r.status, tagClass: r.tagClass, steps: r.steps, next: r.canAdvance ? `→ ${r.nextLabel}` : null,
      })));
      expect(v.empty).toBe(g.empty ? 'x' : null);
      expect(v.rows.every((r) => r.sync === null && r.vigieUrl === `http://localhost:3200/evenements?etat=tous&type=NC&q=${r.number}`)).toBe(true);
    }
  });

  it.each(LANGS)('%s: severity chips are links; filters, selection and the empty message', async (lang) => {
    const v = await ncrTab('HLT-026', lang, { ...S0, ncr: 'NCR-029' });
    expect(v.chips.map((c) => c.href)).toEqual(['', '?filter=minor&', '?filter=major&', '?filter=critical&'].map((q) => `/projects/HLT-026/quality${q ? q : '?'}ncr=NCR-029`));
    expect(v.rows.map((r) => r.selected ? 'var(--color-accent-300)' : 'var(--color-neutral-300)')).toEqual(G[lang].ncrSelected);
    // Row links toggle the drawer and keep the filter.
    expect(v.rows.find((r) => r.number === 'NCR-029')!.href).toBe('/projects/HLT-026/quality');
    expect(v.rows.find((r) => r.number === 'NCR-030')!.href).toBe('/projects/HLT-026/quality?ncr=NCR-030');
    for (const [label, g] of Object.entries(G[lang].ncrFilters) as [string, any][]) {
      const f = (['minor', 'major', 'critical'] as const)[['Minor', 'Major', 'Critical'].indexOf(label)];
      const fv = await ncrTab('HLT-026', lang, { ...S0, filter: f });
      expect(fv.rows.map((r) => r.number)).toEqual(g.rows);
      expect(fv.filter).toBe(f);
      expect(fv.rows[0].href).toBe(`/projects/HLT-026/quality?filter=${f}&ncr=${g.rows[0]}`);
    }
    const empty = await ncrTab('EWA-051', lang);
    expect(empty.rows).toEqual([]);
    expect(empty.empty).toBe(lang === 'en' ? 'No non-conformance reported for this project' : 'Aucune non-conformité signalée pour ce projet');
    // A severity without NCR on a project that has some keeps the prototype's message.
    const noCritical = await ncrTab('NDC-031', lang, { ...S0, filter: 'critical' });
    expect([noCritical.rows.length, noCritical.empty]).toEqual([0, lang === 'en' ? 'No non-conformance at this severity' : 'Aucune non-conformité de cette gravité']);
    expect(empty.kpis.map((k) => k.value)).toEqual(['0', '0', lang === 'en' ? '€0k' : '0 k€', '0', '0']);
  });

  // R-184 (NEW-D1-2): "Action due" has its French (« Échéance de l’action »); the prototype left it in English.
  const actionDue = (lang: Lang, k: string) => (lang === 'fr' && k === 'Action due' ? 'Échéance de l’action' : k);
  it.each(LANGS)('%s: NCR drawers of HLT-026 and NDC-031 (record, causes, steps, severity, next step, links)', async (lang) => {
    for (const code of ['HLT-026', 'NDC-031']) {
      const data = await screen(code);
      for (const n of data.ncrs) {
        const g = G[lang].ncrDrawers[code === 'HLT-026' ? n.number : `${code}:${n.number}`];
        const d = ncrDrawerView({ code, ncr: n, state: { ...S0, ncr: n.number }, viewer: DIRECTOR, ecoByPart: data.ecoByPart, ordersByPart: data.ordersByPart }, makeT(lang), lang);
        expect({
          head: d.head, title: d.title, sev: d.severity, sevClass: d.severityClass, status: d.status, tagClass: d.statusClass, root: d.rootCause, action: d.action,
          steps: d.steps, meta: d.record.map((r) => ({ k: r.k, v: r.v })), sevSeg: d.severities, next: d.move?.label ?? null,
          hasAct: !!d.activityHref, hasPart: !!d.partHref, ecoId: d.eco?.number ?? '',
        }, n.number).toEqual({
          head: `${g.id} · ${g.src}`, title: g.title, sev: g.sev, sevClass: g.sevClass, status: g.status, tagClass: g.tagClass, root: g.root, action: g.action,
          steps: g.steps.map((s: any) => ({ label: s.label, reached: s.dot === 'var(--color-accent)' })), meta: g.meta.map((m: any) => ({ k: actionDue(lang, m.k), v: fix(lang, day(m.v)) })),
          sevSeg: g.sevSeg, next: g.canAdvance ? fix(lang, g.nextLabel) : null, hasAct: g.hasAct, hasPart: g.hasPart, ecoId: g.ecoId,
        });
        expect(d.vigieUrl).toBe(n.vigieUrl);
        expect(d.closeHref).toBe(`/projects/${code}/quality`);
      }
    }
  });

  it('drawer links: activity, part record, open ECO of the part, purchase orders carrying it, impacted deliverable', async () => {
    const data = await screen('HLT-026');
    const view = (num: string) => ncrDrawerView({ code: 'HLT-026', ncr: data.ncrs.find((n) => n.number === num)!, state: S0, viewer: DIRECTOR, ecoByPart: data.ecoByPart, ordersByPart: data.ordersByPart }, makeT('en'), 'en');
    const d30 = view('NCR-030');
    expect([d30.activityHref, d30.partHref, d30.eco]).toEqual(['/projects/HLT-026/plan?act=A1430', '/reference/parts?part=FD-DET-OPT', { number: 'ECO-2026-015', href: '/reference/eco?eco=ECO-2026-015' }]);
    expect(d30.orders.every((o) => o.href === `/projects/HLT-026/orders?po=${o.number}`)).toBe(true);
    expect(data.ordersByPart['FD-DET-OPT'] ?? []).toEqual(d30.orders.map((o) => o.number));
    const d29 = view('NCR-029');
    expect(d29.record.find((r) => r.k === 'Deliverable impacted')).toEqual({ k: 'Deliverable impacted', v: 'D-015', href: '/projects/HLT-026/quality?tab=dlv&dlv=D-015' });
    expect([d29.partHref, d29.eco, d29.orders]).toEqual([null, null, []]);
  });

  it('viewer rules: the client sees no step and no Vigie link; quality verifies; read-only viewers get nothing', async () => {
    const c = await ncrTab('HLT-026', 'en', S0, CLIENT);
    expect(c.rows.every((r) => r.action === null && r.vigieUrl === null)).toBe(true);
    expect(c.mirrorNote).toBe(false);
    const ro = await ncrTab('HLT-026', 'en', S0, { ...PM, canEdit: false });
    expect(ro.rows.every((r) => r.action === null && r.vigieUrl)).toBe(true);
    const data = await screen('HLT-026');
    const ver = { ...data.ncrs.find((n) => n.number === 'NCR-026')!, status: 'verification' as const, statusLabel: 'Verification' };
    const q = ncrDrawerView({ code: 'HLT-026', ncr: ver, state: S0, viewer: { ...DIRECTOR, role: 'quality' }, ecoByPart: {}, ordersByPart: {} }, makeT('fr'), 'fr');
    expect([q.move, q.verify, q.verifyHint]).toEqual([null, { closeLabel: 'Passer à Clôturée', backLabel: 'Retour à l’action corrective' }, null]);
    const p = ncrDrawerView({ code: 'HLT-026', ncr: ver, state: S0, viewer: PM, ecoByPart: {}, ordersByPart: {} }, makeT('en'), 'en');
    expect([p.move, p.verify, p.verifyHint]).toEqual([null, null, 'Verification and closure are decided by the quality manager.']);
  });
});

describe('Deliverables register — EN and FR', () => {
  it.each(LANGS)('%s: KPI tiles, chips and rows of every project with data (project team view)', async (lang) => {
    for (const code of DATA) {
      const g = G[lang].projects[code].dlv;
      const v = await dlvTab(code, lang);
      expect(v.kpis, code).toEqual(g.kpis.map((k: any) => ({ label: k.label, value: k.value, sub: fix(lang, k.sub), color: k.color })));
      expect(v.chips.map((c) => ({ label: c.label, count: c.count })), code).toEqual(g.chips);
      expect(v.rows.map((r) => ({
        id: r.number, title: r.title, type: r.type, wbs: r.wbs, due: r.due, rev: r.rev, acc: r.acceptance, status: r.status, tagClass: r.statusClass,
        raci: r.raci.map((c) => ({ k: c.role, who: c.name, ini: c.initials })), action: r.action?.kind === 'move' ? r.action.label : null,
      })), code).toEqual(g.rows.map((r: any) => ({
        id: r.id, title: r.title, type: fix(lang, r.type), wbs: r.wbs, due: r.id === 'D-021' ? (lang === 'en' ? '14 Jan ’27' : '14 janv. ’27') : r.due, rev: r.rev, acc: r.acc,
        status: r.status, tagClass: r.tagClass, raci: r.raci, action: r.canStart ? r.nextLabel : r.canSubmit ? (lang === 'en' ? 'Submit to client' : 'Soumettre au client') : null,
      })));
    }
  });

  it.each(LANGS)('%s: the client contact accepts or rejects the submitted deliverables; status chips and filters', async (lang) => {
    const c = await dlvTab('HLT-026', lang, { ...S0, tab: 'dlv' }, CLIENT);
    expect(c.rows.map((r) => r.action?.kind === 'decide')).toEqual(G[lang].projects['HLT-026'].dlv.clientRows.map((r: any) => r.canAccept));
    expect(c.rows.some((r) => r.action?.kind === 'move')).toBe(false);
    for (const [label, g] of Object.entries(G[lang].dlvFilters) as [string, any][]) {
      const status = (['planned', 'in_progress', 'internal_review', 'submitted', 'accepted', 'rejected'] as const)[
        ['Planned', 'In progress', 'Internal review', 'Submitted', 'Accepted', 'Rejected', 'Planifié', 'En cours', 'Revue interne', 'Soumis', 'Accepté', 'Refusé'].indexOf(label) % 6];
      const fv = await dlvTab('HLT-026', lang, { ...S0, tab: 'dlv', status });
      expect(fv.rows.map((r) => r.number), label).toEqual(g.rows);
      expect(fv.empty === null, label).toBe(!g.empty);
    }
    const v = await dlvTab('HLT-026', lang, { ...S0, tab: 'dlv', dlv: 'D-015' });
    expect(v.rows.map((r) => (r.selected ? 'var(--color-accent-300)' : 'var(--color-neutral-300)'))).toEqual(G[lang].dlvSelected);
    expect(v.chips[4].href).toBe('/projects/HLT-026/quality?tab=dlv&status=submitted&dlv=D-015');
    expect(v.rows.find((r) => r.number === 'D-015')!.href).toBe('/projects/HLT-026/quality?tab=dlv');
    const none = await dlvTab('EWA-051', lang);
    expect([none.rows.length, none.empty]).toEqual([0, lang === 'en' ? 'No deliverable registered for this project' : 'Aucun livrable enregistré pour ce projet']);
    const noRejected = await dlvTab('HLT-026', lang, { ...S0, tab: 'dlv', status: 'rejected' });
    expect([noRejected.rows.length, noRejected.empty]).toEqual([0, lang === 'en' ? 'No deliverable in this status' : 'Aucun livrable dans ce statut']);
  });

  it.each(LANGS)('%s: deliverable drawers (steps, RACI-B, record, hint, actions) for the project team and the client', async (lang) => {
    const data = await screen('HLT-026');
    for (const d of data.deliverables) {
      for (const [role, viewer] of [['pm', PM], ['client', CLIENT]] as const) {
        const g = G[lang].dlvDrawers[d.number][role];
        const v = dlvDrawerView({ code: 'HLT-026', deliverable: d, state: { ...S0, tab: 'dlv', dlv: d.number }, viewer, documents: data.documents }, makeT(lang), lang);
        expect({
          head: v.head, title: v.title, status: v.status, tagClass: v.statusClass, steps: v.steps, raci: v.raci, meta: v.record.map((r) => ({ k: r.k, v: r.v })),
          hint: v.hint, canSubmit: v.canSubmit, canAccept: v.canDecide,
        }, `${d.number} ${role}`).toEqual({
          head: `${g.id} · ${fix(lang, g.type)}`, title: g.title, status: g.status, tagClass: g.tagClass,
          steps: g.steps.map((s: any) => ({ label: s.label, reached: s.dot === 'var(--color-accent)' })),
          raci: g.raci.map((r: any) => ({ k: r.k, l: r.l, who: r.who })),
          meta: g.meta.map((m: any) => ({ k: m.k, v: d.number === 'D-021' && m.v === (lang === 'en' ? '14 Jan' : '14 janv.') ? (lang === 'en' ? '14 Jan ’27' : '14 janv. ’27') : fix(lang, m.v) })),
          hint: g.hint, canSubmit: g.canSubmit, canAccept: g.canAccept,
        });
        expect(v.planHref).toBe('/projects/HLT-026/plan');
      }
    }
    const d15 = dlvDrawerView({ code: 'HLT-026', deliverable: data.deliverables.find((d) => d.number === 'D-015')!, state: S0, viewer: PM, documents: data.documents }, makeT(lang), lang);
    expect(d15.record.find((r) => r.links)?.links).toEqual([{ label: 'NCR-029', href: '/projects/HLT-026/quality?ncr=NCR-029' }]);
    expect([d15.document, d15.canLinkDocument, d15.depositType]).toEqual([null, true, null]);
    expect(d15.documentOptions.length).toBeGreaterThan(0);
    expect(d15.documentOptions.every((o) => o.label.startsWith(o.value + ' · '))).toBe(true);
  });

  it('NDC-031: D-110…D-113 with R = the project’s PM; drawer record of the generated rows', async () => {
    const data = await screen('NDC-031');
    for (const d of data.deliverables) {
      const g = G.en.dlvDrawers[`NDC-031:${d.number}`].pm;
      const v = dlvDrawerView({ code: 'NDC-031', deliverable: d, state: S0, viewer: PM, documents: data.documents }, makeT('en'), 'en');
      expect(v.raci.map((r) => r.who)).toEqual(g.raci.map((r: any) => r.who));
      expect(v.record.map((r) => ({ k: r.k, v: r.v }))).toEqual(g.meta);
    }
  });
});
